const rawPayload = $json.body ?? $json;
const plainOcrText = typeof rawPayload === 'string' ? rawPayload : '';
const safeText = plainOcrText.toString();
const trimmed = safeText.length > 1000 ? safeText.slice(0, 1000) : safeText;

const prompt = `You are an invoice validation expert. Analyze if the following OCR-extracted text represents a coherent, legitimate invoice or if it's gibberish/fake.

OCR Text:
${trimmed}

Rate the text coherence from 0-100:
- 0-30: Complete gibberish, random characters, or clearly fake
- 31-60: Highly fragmented, missing key invoice elements
- 61-80: Recognizable invoice structure but with OCR errors
- 81-100: Clear, coherent invoice with proper structure

Respond in JSON format:
{
  \"sense_rating\": <number 0-100>,
  \"reasoning\": \"<brief explanation>\"
}`;

return {
  json: {
    formatted_prompt: prompt,
    original_text_length: safeText.length
  }
};

const modelOutput = ($json.response || '').toString();

try {
  const parsed = JSON.parse(modelOutput);
  const rawRating = parsed.sense_rating;
  const numericRating = typeof rawRating === 'number' ? rawRating : Number(rawRating);

  return {
    json: {
      sense_rating: Number.isFinite(numericRating) ? Math.max(0, Math.min(100, numericRating)) : 50,
      reasoning: (parsed.reasoning || 'No reasoning provided').toString()
    }
  };
} catch (error) {
  return {
    json: {
      sense_rating: 50,
      reasoning: 'LLM response parsing failed'
    }
  };
}
